class CapitalEntry {
  final String capital;
  final String country;
  final String continent;
  final String flagEmoji;
  final double lat;
  final double lng;
  final List<DecoyCity> decoyCities;
  final int neighbours;        // number of land borders
  final int capitalPopulation; // city proper population (thousands)

  const CapitalEntry({
    required this.capital,
    required this.country,
    required this.continent,
    required this.flagEmoji,
    required this.lat,
    required this.lng,
    this.decoyCities = const [],
    this.neighbours = 0,
    this.capitalPopulation = 0,
  });

  // capitalPopulation is stored in thousands. Show "1.4m" once a city
  // passes a million people; otherwise show the plain "480k" form.
  String get populationLabel {
    if (capitalPopulation >= 1000) {
      final millions = capitalPopulation / 1000;
      return '${millions.toStringAsFixed(1)}m';
    }
    return '${capitalPopulation}k';
  }
}

class DecoyCity {
  final String name;
  final double lat;
  final double lng;
  const DecoyCity(this.name, this.lat, this.lng);
}

